    { id: "wr", name: "2. Writing Skills", w: "high", wx: "Typical: letters + essays — 15m+, highest scorer", notes: ["Letter: formal (block format, subject, date) vs informal (warm tone). 5 marks = format + content + grammar.","Dialogue/report/speech: tense consistency + reported speech rules.","Expansion of theme: explain → illustrate → conclude (proverb).","Essay/story: outline first, 250–300 words, paragraphing."," précis: one-third length, own words, title."], traps: ["Formal letter needs subject line + subscription (Yours faithfully).", "Report = past tense, passive preferred."], formulas: [] },
    { id: "rc", name: "3. Comprehension Strategy", w: "mid", wx: "Typical: passages + poetry — practice-based", notes: ["Read questions first, then passage; underline dates/names.","Poetry: theme + rhyme + figure of speech (simile, metaphor, personification, alliteration).","Vocabulary: synonyms/antonyms from context, word formation.","Summary writing: pick key sentences, join with linkers.","Time split: 3 hrs/80 marks ≈ 2.25 min per mark — don't overspend on writing."], traps: ["Figure of speech needs the exact quoted line.", "Summary must not copy full sentences."], formulas: [] }
